{
  "findings": [
    {
      "ref": "R444",
      "area": "contact",
      "claim": "A parent reports the app talks too long.",
      "stance": "risk",
      "quote": "It’s really good this app is it just the talking is too long it talking more then you play.please change this"
    },
    {
      "ref": "R455",
      "area": "contact",
      "claim": "A parent reports they cannot find a verify email button and cannot log in.",
      "stance": "risk",
      "quote": "I don’t see a verify email button all I see is next button and I can’t log in"
    },
    {
      "ref": "R467",
      "area": "contact",
      "claim": "A parent reports they need to use an email address and wants to change it, indicating account setup involves personal data.",
      "stance": "neutral",
      "quote": "How to use your email address like all all the learning games I’ve been using so if you could please change it I would like you to"
    },
    {
      "ref": "R488",
      "area": "contact",
      "claim": "A parent reports a home button exits a lesson without confirmation, causing loss of progress and frustration for young children.",
      "stance": "risk",
      "quote": "Great app with lots of content across reading, writing, math, general knowledge. My one big complaint is that during each lesson there is a home icon button that exits out of the current lesson with no confirmation. You lose your progress and can’t immediately open the lesson back up (unless you find it in the library). Another random lesson opens. This happens so often with my young kids, and it’s so frustrating. Can you please add a confirmation dialog if the home button is pressed before the lesson is over?"
    },
    {
      "ref": "R476",
      "area": "money",
      "claim": "A parent reports the app lacks harder levels, implying limited progression and potential for in-app purchases to unlock more content.",
      "stance": "risk",
      "quote": "I need harder educational levels to learn more."
    },
    {
      "ref": "R486",
      "area": "money",
      "claim": "A parent suggests adding more grades and passcodes to prevent children from switching levels, indicating concerns about content appropriateness and potential monetization of advanced levels.",
      "stance": "mitigation",
      "quote": "Maybe could make it so switching grades wasn’t so available to kids, and you can add a passcode on it, so they don’t switch the grades?"
    },
    {
      "ref": "R473",
      "area": "content",
      "claim": "A parent reports the app includes stories with morals that evoke emotional responses, such as making them tear up.",
      "stance": "neutral",
      "quote": "Some of the lesson based stories have such good morals it makes me tear up!"
    },
    {
      "ref": "R482",
      "area": "content",
      "claim": "A parent reports the app includes stories about wildlife and sports that teach respect for animals and teamwork.",
      "stance": "neutral",
      "quote": "There are categories for topics like wildlife and sports as well, perfect for teaching about respecting animals or about teamwork."
    },
    {
      "ref": "R493",
      "area": "content",
      "claim": "A parent reports the app has no ads and is super educational and fun, with offline games.",
      "stance": "mitigation",
      "quote": "No ad super educational but fun. There are lots of off-line games that you can play and educational stuff stuff two years plus the best app I’ve ever downloaded!!!!!"
    },
    {
      "ref": "R496",
      "area": "data",
      "claim": "A parent reports they cannot find language settings, indicating possible data collection or lack of user control over language preferences.",
      "stance": "risk",
      "quote": "Can’t find language settings boo"
    },
    {
      "ref": "R475",
      "area": "data",
      "claim": "A parent reports the app crashes frequently, which may indicate unstable data handling or potential exposure of user data during errors.",
      "stance": "risk",
      "quote": "Every game we open gives an error and we can’t do anything."
    },
    {
      "ref": "R479",
      "area": "data",
      "claim": "A parent reports that switching a child's account causes the app to crash, raising concerns about account data management.",
      "stance": "risk",
      "quote": "Only one of my kids can use the app, when we select the other child’s account the app crashes."
    },
    {
      "ref": "R484",
      "area": "data",
      "claim": "A parent reports the app is only compatible with mobile and tablet devices, limiting accessibility and potentially requiring device-specific data collection.",
      "stance": "neutral",
      "quote": "Academy is only compatible with cellular or tablet devices. it is not available for Windows 10 or any of those computers"
    },
    {
      "ref": "R477",
      "area": "age_gating",
      "claim": "A parent reports the app is labeled as suitable for ages 5-8 but their child is in fifth grade, indicating a mismatch between advertised age range and actual usability.",
      "stance": "risk",
      "quote": "My daughter is now in fifth grade, and the app is only available ages 5-8."
    },
    {
      "ref": "R462",
      "area": "age_gating",
      "claim": "A parent reports the app only goes up to second grade, and their third-grade child found it no longer fun, indicating the age gate does not work in practice for older children.",
      "stance": "risk",
      "quote": "My child is in 3rd grade and the app only has pre-k to 2nd grade. she loved it last year but now it’s not as fun anymore because it is not her level anymore."
    },
    {
      "ref": "R463",
      "area": "age_gating",
      "claim": "A parent reports the app cuts off learning for children above second grade, and they explicitly request expansion to grade 5, showing the current age gate is too restrictive.",
      "stance": "risk",
      "quote": "I gave the review four stars solely for the reason that this fantastic app sadly cuts off learning for children above second grade. My daughter absolutely loves this app for learning through fun and games. She has been playing this app for years and sadly it cannot take her any further."
    },
    {
      "ref": "R486",
      "area": "developer_record",
      "claim": "A parent reports the app has no free trials or payments, which may indicate a sustainable free model without aggressive monetization, but does not provide evidence of regulatory issues.",
      "stance": "neutral",
      "quote": "I am a tutor for speech physical etc you get it and I love this app and it has no free trials no payments just plain on FREE I luv it so much!"
    }
  ]
}
